      "Diante de Deus, sem precisar apresentar uma resposta perfeita: Que decisão atual exige que você resista à opinião da maioria em nome da justiça?",
      "Pensando na sua caminhada de hoje: Como cultivar discernimento pessoal que não depende de aprovação social para se manter firme?"
