    "application": "Hoje, sem transformar este convite em cobrança, identifique hoje uma situação em que você tem seguido a maioria contra seu próprio discernimento, e reconsidere sua posição.",
    "prayer": "Senhor, recebe meu coração como ele está hoje. dá-me coragem para não seguir a maioria quando ela se afasta da tua justiça. Amém.",
    "passage": {
      "ref": "Êxodo 23 · capítulo completo (NVI)",
      "verses": [
        {
          "n": 1,
          "text": "\"Não faça declarações falsas e não seja cúmplice do ímpio, sendo-lhe testemunha mal-intencionada."
        },
        {
          "n": 2,
          "text": "\"Não acompanhe a maioria para fazer o mal. Ao testemunhar num processo, não perverta a justiça para apoiar a maioria,"
        },
        {
          "n": 3,
          "text": "nem para favorecer o pobre num processo."
        },
        {
          "n": 4,
          "text": "\"Se você encontrar perdido o boi ou o jumento que pertence ao seu inimigo, leve-o de volta a ele."
        },
        {
          "n": 5,
          "text": "Se você vir o jumento de alguém que o odeia caído sob o peso de sua carga, não o abandone, procure ajudá-lo."
        },
        {
          "n": 6,
          "text": "\"Não perverta o direito dos pobres em seus processos."
        },
        {
          "n": 7,
          "text": "Não se envolva em falsas acusações nem condene à morte o inocente e o justo, porque não absolverei o culpado."
        },
        {
          "n": 8,
          "text": "\"Não aceite suborno, pois o suborno cega até os que têm discernimento e prejudica a causa do justo."
        },
        {
          "n": 9,
          "text": "\"Não oprima o estrangeiro. Vocês sabem o que é ser estrangeiro, pois foram estrangeiros no Egito."
        },
        {
          "n": 10,
          "text": "\"Plantem e colham em sua terra durante seis anos,"
        },
        {
          "n": 11,
          "text": "mas no sétimo deixem-na descansar sem cultivá-la. Assim os pobres do povo poderão comer o que crescer por si, e o que restar ficará para os animais do campo. Façam o mesmo com as suas vinhas e com os seus olivais."
        },
        {
          "n": 12,
          "text": "\"Em seis dias façam os seus trabalhos, mas no sétimo não trabalhem, para que o seu boi e o seu jumento possam descansar, e o seu escravo e o estrangeiro renovem as forças."
        },
        {
          "n": 13,
          "text": "\"Tenham o cuidado de fazer tudo o que lhes ordenei. Não invoquem o nome de outros deuses; não se ouçam tais nomes dos seus lábios. \""
        },
        {
          "n": 14,
          "text": "\"Três vezes por ano vocês me celebrarão festa."
        },
        {
          "n": 15,
          "text": "\"Celebrem a festa dos pães sem fermento; durante sete dias comam pão sem fermento, como eu lhes ordenei. Façam isto na época determinada do mês de abibe, pois nesse mês vocês saíram do Egito. \"Ninguém se apresentará a mim de mãos vazias."
        },
        {
          "n": 16,
          "text": "\"Celebrem a festa da colheita dos primeiros frutos do seu trabalho de semeadura. \"Celebrem a festa do encerramento da colheita, quando, no final do ano, vocês armazenarem as colheitas."
        },
        {
          "n": 17,
          "text": "\"Três vezes por ano todos os homens devem comparecer diante do Senhor soberano."
        },
        {
          "n": 18,
          "text": "\"Não ofereçam o sangue de um sacrifício feito em minha honra com pão fermentado. \"A gordura das ofertas de minhas festas não deverá ser guardada até a manhã seguinte."
        },
        {
          "n": 19,
          "text": "\"Tragam ao santuário do Senhor seu Deus o melhor dos primeiros frutos das suas colheitas. \"Não cozinhem o cabrito no leite da própria mãe."
        },
        {
          "n": 20,
          "text": "\"Eis que envio um anjo à frente de vocês para protegê-los por todo o caminho e fazê-los chegar ao lugar que preparei."
        },
        {
          "n": 21,
          "text": "Prestem atenção e ouçam o que ele diz. Não se rebelem contra ele, pois não perdoará as suas transgressões, pois nele está o meu nome."
        },
        {
          "n": 22,
          "text": "Se vocês ouvirem atentamente o que ele disser e fizerem tudo o que lhes ordeno, serei inimigo dos seus inimigos, e adversário dos seus adversários."
        },
        {
          "n": 23,
          "text": "O meu anjo irá à frente de vocês e os fará chegar à terra dos amorreus, dos hititas, dos ferezeus, dos cananeus, dos heveus e dos jebuseus, e eu os exterminarei."
        },
        {
          "n": 24,
          "text": "Não se curvem diante dos deuses deles, nem lhes prestem culto, nem sigam as suas práticas. Destruam-nos totalmente e quebrem as suas colunas sagradas."
        },
        {
          "n": 25,
          "text": "Prestem culto ao Senhor, o Deus de vocês, e ele os abençoará, dando-lhes alimento e água. Tirarei a doença do meio de vocês."
        },
        {
          "n": 26,
          "text": "Em sua terra nenhuma grávida perderá o filho, nem haverá mulher estéril. Farei completar-se o tempo de duração da vida de vocês."
        },
        {
          "n": 27,
          "text": "\"Mandarei adiante de vocês o meu terror, que porá em confusão todas as nações que vocês encontrarem. Farei que todos os seus inimigos virem as costas e fujam."
        },
        {
          "n": 28,
          "text": "Causarei pânico entre os heveus, os cananeus e os hititas para expulsá-los de diante de vocês."
        },
        {
          "n": 29,
          "text": "Não os expulsarei num só ano, pois a terra se tornaria desolada e os animais selvagens se multiplicariam, ameaçando vocês."
        },
        {
          "n": 30,
          "text": "Eu os expulsarei aos poucos, até que vocês sejam numerosos o suficiente para tomar posse da terra."
        },
        {
          "n": 31,
          "text": "\"Estabelecerei as suas fronteiras desde o mar Vermelho até o mar dos filisteus, e desde o deserto até o Rio. Entregarei em suas mãos os povos que vivem na terra, aos quais expulsarão de diante de vocês."
        },
        {
          "n": 32,
          "text": "Não façam aliança com eles nem com os seus deuses."
        },
        {
          "n": 33,
          "text": "Não deixem que esses povos morem na terra de vocês, senão eles os levarão a pecar contra mim, porque prestar culto aos deuses deles será uma armadilha para vocês. \""
        }
      ]
    }
