          "n": 6,
          "text": "Se o seu próprio irmão ou filho ou filha, ou a mulher que você ama ou o seu amigo mais chegado secretamente instigá-lo, dizendo: \"Vamos adorar outros deuses! \" — deuses que nem você nem os seus antepassados conheceram,"
